(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1x = Math.sin(x*0.015+t*0.2)*20 + Math.cos(y*0.02-t*0.15)*15;
  const warp1y = Math.cos(y*0.018-t*0.25)*18 + Math.sin(x*0.012+t*0.3)*12;
  const warp2x = Math.sin((x+warp1x)*0.025-t*0.4)*10 + Math.cos((y+warp1y)*0.03+t*0.35)*8;
  const warp2y = Math.cos((y+warp1y)*0.022+t*0.45)*10 + Math.sin((x+warp1x)*0.028-t*0.38)*7;
  const sx = x+warp1x+warp2x, sy = y+warp1y+warp2y;
  const src = [
    [160+Math.sin(t*0.5)*120, 80+Math.cos(t*0.35)*60, 0.07, 2.2],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.6)*55, 0.09, 1.8],
    [240+Math.sin(t*0.25+2)*160, 120+Math.cos(t*0.4+1)*100, 0.055, 2.5],
    [120+Math.cos(t*0.7+1)*90, 180+Math.sin(t*0.55+3)*70, 0.11, 1.6],
    [360+Math.sin(t*0.35+4)*100, 60+Math.cos(t*0.8+2)*80, 0.065, 2.8],
    [240+Math.cos(t*0.3+5)*130, 200+Math.sin(t*0.5)*90, 0.08, 2.1],
    [80+Math.sin(t*0.55+3)*70, 40+Math.cos(t*0.65+1)*50, 0.13, 1.4],
    [400+Math.cos(t*0.4+2)*60, 200+Math.sin(t*0.45+4)*65, 0.075, 2.4],
    [200+Math.sin(t*0.32)*90, 220+Math.cos(t*0.48+2)*70, 0.1, 1.9],
    [300+Math.cos(t*0.58+1)*85, 30+Math.sin(t*0.38+3)*55, 0.085, 2.6]
  ];
  let aS=0, iS=0, aH=0, iH=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w=Math.sin(d*f-t*sp);
    aS+=w; aH+=w*Math.exp(-d*0.003);
    const w2=Math.sin(d*f*0.6+t*sp*0.5+2.1);
    iS+=w2; iH+=w2*Math.exp(-d*0.004);
  }
  const act=aS/10, inh=iS/10, actH=aH/10, inhH=iH/10;
  const n1=Math.sin(sx*0.035+sy*0.022+t*0.7)*Math.cos(sx*0.028-sy*0.04+t*0.9);
  const n2=Math.sin((sx+sy)*0.1+t*2.2)*0.3+Math.sin((sx-sy)*0.08-t*1.8)*0.3;
  const n3=Math.sin(sx*0.07+t*1.5)*Math.sin(sy*0.065-t*1.3)*0.25;
  const bg=n1+n2+n3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*4-t*1.3)+Math.sin(dist*0.035+ang*5-t*1.0);
  const sp2=Math.sin(dist*0.06-ang*2+t*0.8)*Math.cos(dist*0.025+ang*3-t*1.6);
  const spiral=(sp1*0.35+sp2*0.25);
  const lap=bg*0.2+spiral*0.3;
  const feed=0.055+Math.sin(t*0.2)*0.01, kill=0.062+Math.cos(t*0.15)*0.008;
  const da=actH*2.0-inhH*3.0+lap*0.5;
  const di=-inhH*1.0+actH*2.5+lap*0.3;
  const diffA=Math.tanh((da+act*0.5+bg*0.25+spiral)*2.5);
  const diffB=Math.tanh((di-inh*0.4-bg*0.15)*2.0);
  const reaction=Math.tanh((diffA-diffB*0.6+diffA*diffB*0.8)*2.0);
  const cellA=Math.sin(sx*0.14)*Math.sin(sy*0.14);
  const cellB=Math.sin((sx+sy)*0.09+t*0.8)*Math.cos((sx-sy)*0.11-t*0.6);
  const cell=Math.tanh((cellA+cellB*0.7)*1.8)*0.25;
  const micro=Math.sin(sx*0.4+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
  const edge=1.0+Math.pow(Math.abs(reaction),3)*0.4;
  const glow=Math.exp(-Math.abs(reaction)*2)*0.15;
  const blend=reaction*0.6+cell*0.2+micro+glow;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,55],[10,45,95],[15,95,125],[20,155,145],
    [55,185,130],[140,200,85],[210,185,55],
    [225,140,60],[215,90,65],[185,55,75],
    [130,35,70],[75,20,55],[30,12,48],[5,12,55]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const cr=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const cg=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const cb=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const sat=1.0+Math.abs(reaction)*0.15;
  const gray=(cr+cg+cb)/3;
  return[
    Math.min(255,((cr+(cr-gray)*sat*0.3)*lum*edge)|0),
    Math.min(255,((cg+(cg-gray)*sat*0.3)*lum*edge)|0),
    Math.min(255,((cb+(cb-gray)*sat*0.3)*lum*edge)|0)
  ];
}
